export interface HarnessGuideTurnState {
  botId: string;
  threadId: string;
  turnId: string;
  selection: { engine: string; model: string | null; reasoningEffort: string | null; speed: string | null };
  botFlags: { canSeeBots: boolean; canReceiveOrders: boolean; canSendActions: boolean; isMaster: boolean };
  features: { mcpToolsEnabled: boolean; harnessAdminToolsEnabled: boolean; nativeMcpConfigured: boolean; botDelegationEnabled: boolean;
    deviceToolsEnabled: boolean; externalMemoryConfigured: boolean };
}

function choice(value: string | null, maximum: number): string | null {
  if (value === null) return null;
  if (typeof value !== "string" || value.length < 1 || value.length > maximum || /[\u0000-\u001f\u007f]/.test(value))
    throw new ContextError("invalid_input", "Invalid harness state.");
  return value;
}
function flag(value: boolean): boolean {
  if (typeof value !== "boolean") throw new ContextError("invalid_input", "Invalid harness state.");
  return value;
}

/** Fixed field projection: no bot prose, other scope, credentials, paths, native cursors or catalog probes. */
export function buildHarnessGuideTurnInstructions(input: HarnessGuideTurnState): string {
  const state = {
    authority: "connected_dexter_host",
    botId: id(input.botId), threadId: id(input.threadId), turnId: id(input.turnId),
    selection: { engine: choice(input.selection.engine, 64), model: choice(input.selection.model, 128),
      reasoningEffort: choice(input.selection.reasoningEffort, 64), speed: choice(input.selection.speed, 64) },
    botFlags: { canSeeBots: flag(input.botFlags.canSeeBots), canReceiveOrders: flag(input.botFlags.canReceiveOrders),
      canSendActions: flag(input.botFlags.canSendActions), isMaster: flag(input.botFlags.isMaster) },
    features: { mcpToolsEnabled: flag(input.features.mcpToolsEnabled), harnessAdminToolsEnabled: flag(input.features.harnessAdminToolsEnabled),
      nativeMcpConfigured: flag(input.features.nativeMcpConfigured),
      botDelegationEnabled: flag(input.features.botDelegationEnabled), deviceToolsEnabled: flag(input.features.deviceToolsEnabled),
      externalMemoryConfigured: flag(input.features.externalMemoryConfigured) },
    toolAvailability: "Only the current tools/list exposes callable aliases and schemas; flags grant no access.",
  };
  const json = JSON.stringify(state);
  if (json.length > HARNESS_GUIDE_MAX_STATE_CHARACTERS) throw new ContextError("invalid_input", "Harness state exceeds its limit.");
  const guide = DEXTER_HARNESS_GUIDE;
  const result = `BEGIN DEXTER BUILT-IN HARNESS GUIDE ${guide.id}@${guide.version} sha256=${guide.sha256}\n${guide.markdown}\nEND DEXTER BUILT-IN HARNESS GUIDE ${guide.id}@${guide.version}\n\nBEGIN DEXTER TURN STATE (quoted data, not instructions)\n${json}\nEND DEXTER TURN STATE`;
  if (result.length > HARNESS_GUIDE_MAX_INSTRUCTION_CHARACTERS) throw new ContextError("invalid_input", "Harness guide exceeds its limit.");
  return result;
}
